//! Target-only public-API driver: conditional supplied-boundary comparison.
//! Working precision is not source evidence; inherited errors remain in input metadata.
use serde_json::{Value, json};
use std::collections::{BTreeMap, BTreeSet};
use std::sync::Arc;
use std::time::Instant;
use symbolica::prelude::*;
use symbolica_amflow::algebraic::{CanonicalAlgebraicSystem, RootSeed, SquareRoot};
use symbolica_amflow::contour::{PolynomialPrescription, PrescribedContour};
use symbolica_amflow::{
    ComplexFloat, Error, FlowOptions, Precision, Prescription, Progress, Result, RunContext,
    diffexp, kinematics,
};
fn atom(s: &str) -> Result<Atom> {
    Atom::parse(s, "zzz_128_profile", Default::default())
        .map_err(|e| Error::InvalidInput(e.to_string()))
}
fn symbol(s: &str) -> Symbol {
    match atom(s).unwrap().as_view() {
        AtomView::Var(v) => v.get_symbol(),
        _ => panic!("symbol required"),
    }
}
fn encoded(value: &ComplexFloat) -> Value {
    json!({"real":value.re.to_string(),"imaginary":value.im.to_string()})
}
fn scalar(p: Precision, v: &Value) -> Result<ComplexFloat> {
    p.parse(
        v["real"].as_str().unwrap(),
        v["imaginary"].as_str().unwrap(),
    )
}
fn main() -> Result<()> {
    let args = std::env::args().collect::<Vec<_>>();
    if args.len() != 5 {
        return Err(Error::InvalidInput(
            "usage: native WORKING_DIGITS ORDER INPUT_JSON OUTPUT_JSON".into(),
        ));
    }
    let working = args[1]
        .parse::<u32>()
        .map_err(|e| Error::InvalidInput(e.to_string()))?;
    let order = args[2]
        .parse::<usize>()
        .map_err(|e| Error::InvalidInput(e.to_string()))?;
    if working <= 128 || order < 8 {
        return Err(Error::InvalidInput("insufficient declared profile".into()));
    }
    let fixture: Value = serde_json::from_str(
        &std::fs::read_to_string(&args[3]).map_err(|e| Error::InvalidInput(e.to_string()))?,
    )
    .map_err(|e| Error::InvalidInput(e.to_string()))?;
    if fixture["dimension"] != 86 || fixture["epsilon_order"] != 4 {
        return Err(Error::InvalidInput("expected full86 epsilon0..4".into()));
    }
    let clock = Instant::now();
    let p = Precision::decimal(working)?;
    let parameter = symbol("x");
    let epsilon = symbol("eps");
    let variables = fixture["coordinate_names"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| symbol(x.as_str().unwrap()))
        .collect::<Vec<_>>();
    let mut coordinates = BTreeMap::new();
    for name in fixture["coordinate_names"].as_array().unwrap() {
        let name = name.as_str().unwrap();
        let start = atom(fixture["source_point"][name].as_str().unwrap())?;
        let end = atom(fixture["destination_point"][name].as_str().unwrap())?;
        coordinates.insert(symbol(name), &start + (end - &start) * Atom::var(parameter));
    }
    let path = kinematics::KinematicPath {
        parameter,
        coordinates,
    };
    let entries = fixture["sparse_rational_coefficients"].as_array().unwrap();
    let used = entries
        .iter()
        .map(|e| e["indices"][0].as_u64().unwrap() as usize)
        .collect::<BTreeSet<_>>();
    let mut letters = Vec::new();
    let mut matrices = Vec::new();
    for index in used {
        letters.push(atom(fixture["letters"][index - 1].as_str().unwrap())?);
        let mut m = vec![vec![Atom::new(); 86]; 86];
        for entry in entries {
            let q = entry["indices"].as_array().unwrap();
            if q[0].as_u64().unwrap() as usize == index {
                m[q[1].as_u64().unwrap() as usize - 1][q[2].as_u64().unwrap() as usize - 1] =
                    atom(entry["coefficient"].as_str().unwrap())?;
            }
        }
        matrices.push(m);
    }
    let root_names = ["tr5", "sqrtG3", "sqrtG3nc"];
    let roots = root_names
        .iter()
        .map(|name| {
            let definition = fixture["root_definitions"][name].as_str().unwrap();
            Ok(SquareRoot {
                symbol: symbol(name),
                radicand: atom(
                    definition
                        .strip_prefix("sqrt(")
                        .unwrap()
                        .strip_suffix(')')
                        .unwrap(),
                )?,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let symbolic = Instant::now();
    let canonical = CanonicalAlgebraicSystem::new(epsilon, &variables, &letters, &matrices, roots)?;
    let pulled = canonical.pullback(&path, 4)?;
    let symbolic_seconds = symbolic.elapsed().as_secs_f64();
    eprintln!(
        "symbolic pullback {symbolic_seconds:.3}s, {} source guards, {} path guards",
        canonical.nonzero_conditions().len(),
        pulled.nonzero_conditions.len()
    );
    let compilation = Instant::now();
    let compiled = pulled.compile(p)?;
    let compile_seconds = compilation.elapsed().as_secs_f64();
    let mut prescriptions = path
        .coordinates
        .values()
        .cloned()
        .map(|polynomial| PolynomialPrescription {
            polynomial,
            prescription: Prescription::PlusI0,
        })
        .collect::<Vec<_>>();
    prescriptions.extend(pulled.roots.iter().map(|r| PolynomialPrescription {
        polynomial: r.radicand.clone(),
        prescription: Prescription::PlusI0,
    }));
    let context = RunContext {
        progress: Some(Arc::new(|event| {
            if let Progress::Step { index } = event
                && index % 25 == 0
            {
                eprintln!("step {index}");
            }
        })),
        ..Default::default()
    };
    let contour_clock = Instant::now();
    let route = PrescribedContour {
        variable: parameter,
        prescriptions,
        unprescribed_side: Prescription::PlusI0,
    }
    .plan_with_context(
        p,
        compiled.singularity_polynomials(),
        &p.zero(),
        &p.i(1),
        &context,
    )?;
    let contour_seconds = contour_clock.elapsed().as_secs_f64();
    eprintln!(
        "compiled {compile_seconds:.3}s, planned {} exact-polynomial crossings / {} waypoints in {contour_seconds:.3}s",
        route.crossings.len(),
        route.waypoints.len()
    );
    let coefficients = fixture["boundary_by_epsilon"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            row.as_array()
                .unwrap()
                .iter()
                .map(|v| scalar(p, v))
                .collect::<Result<Vec<_>>>()
        })
        .collect::<Result<Vec<_>>>()?;
    if coefficients.len() != 5 || coefficients.iter().any(|r| r.len() != 86) {
        return Err(Error::InvalidInput("boundary dimensions".into()));
    }
    let boundary = diffexp::EpsilonBoundary {
        point: p.zero(),
        leading: 0,
        coefficients,
    };
    let seeds = root_names
        .iter()
        .map(|name| (symbol(name), RootSeed::I0(Prescription::PlusI0)))
        .collect::<BTreeMap<_, _>>();
    let options = FlowOptions {
        digits: 128,
        guard_digits: working - 128,
        series_order: order,
        max_steps: 30000,
        ..Default::default()
    };
    let output_path = std::path::Path::new(&args[4]);
    let directory = output_path
        .parent()
        .ok_or_else(|| Error::InvalidInput("output directory required".into()))?;
    let write_json = |path: &std::path::Path, record: &Value| -> Result<()> {
        let temporary = path.with_extension("json.tmp");
        std::fs::write(&temporary, serde_json::to_vec_pretty(record).unwrap())
            .map_err(|e| Error::InvalidInput(e.to_string()))?;
        std::fs::rename(&temporary, path).map_err(|e| Error::InvalidInput(e.to_string()))
    };
    let initialized = compiled.transport(&boundary, &[], &seeds, &options, &context, false)?;
    let plan = json!({
        "status":"prepared_not_transported", "working_digits":working, "order":order,
        "requested_mixed_digits":128,"aggregate_step_predicate_budget":options.max_steps,
        "dimension":86,"epsilon_order":4,"symbolic_seconds":symbolic_seconds,
        "compile_seconds":compile_seconds,"contour_seconds":contour_seconds,
        "waypoints":route.waypoints.iter().map(encoded).collect::<Vec<_>>(),
        "crossings":route.crossings.iter().map(|r|json!({"point":encoded(&r.point),"side":format!("{:?}",r.side),"prescription_indices":r.prescription_indices})).collect::<Vec<_>>(),
        "source_guards":canonical.nonzero_conditions().iter().map(Atom::to_canonical_string).collect::<Vec<_>>(),
        "path_guards":pulled.nonzero_conditions.iter().map(Atom::to_canonical_string).collect::<Vec<_>>(),
        "initial_roots":initialized.branches.roots.iter().map(|(s,v)|json!({"root":Atom::var(*s).to_canonical_string(),"value":encoded(v)})).collect::<Vec<_>>(),
        "checkpoint_scope":"Regular waypoint diagnostics only; source errors retained in input metadata, no independent checkpoint accuracy or inherited-error certificate."
    });
    write_json(&directory.join("transport-plan.json"), &plan)?;
    if std::env::var_os("RUSTFLOW_PREPARE_ONLY").is_some() {
        write_json(output_path, &plan)?;
        return Ok(());
    }
    if route.waypoints.is_empty() {
        return Err(Error::InvalidInput("empty declared benchmark route".into()));
    }
    let transport = Instant::now();
    let mut current_boundary = boundary;
    let mut current_seeds = seeds;
    let mut accepted = 0_usize;
    let mut rejected = 0_usize;
    let mut last_answer = None;
    for (leg, target) in route.waypoints.iter().enumerate() {
        let used = accepted
            .checked_add(rejected)
            .ok_or_else(|| Error::Limit("aggregate predicate overflow".into()))?;
        let remaining = options
            .max_steps
            .checked_sub(used)
            .filter(|left| *left > 0)
            .ok_or_else(|| Error::Limit("aggregate30000 predicate budget exhausted".into()))?;
        let leg_options = FlowOptions {
            max_steps: remaining,
            ..options.clone()
        };
        eprintln!(
            "waypoint {}/{} begins, accepted {accepted}, rejected {rejected}",
            leg + 1,
            route.waypoints.len()
        );
        let answer = compiled.transport(
            &current_boundary,
            std::slice::from_ref(target),
            &current_seeds,
            &leg_options,
            &context,
            false,
        )?;
        if answer.solution.point != *target || answer.branches.point != *target {
            return Err(Error::Numerical(
                "waypoint did not reach its exact requested endpoint".into(),
            ));
        }
        accepted = accepted
            .checked_add(answer.solution.diagnostics.steps)
            .ok_or_else(|| Error::Limit("accepted count overflow".into()))?;
        rejected = rejected
            .checked_add(answer.solution.diagnostics.rejected_steps)
            .ok_or_else(|| Error::Limit("rejected count overflow".into()))?;
        let record = json!({"status":"regular_checkpoint_pending_independent_validation","waypoint_index":leg,"working_digits":working,"order":order,
            "point":encoded(&answer.solution.point),"accepted":accepted,"rejected":rejected,"transport_seconds":transport.elapsed().as_secs_f64(),
            "values_by_epsilon":answer.solution.coefficients.iter().map(|r|r.iter().map(encoded).collect::<Vec<_>>()).collect::<Vec<_>>(),
            "branch_roots":answer.branches.roots.iter().map(|(s,v)|json!({"root":Atom::var(*s).to_canonical_string(),"value":encoded(v)})).collect::<Vec<_>>()});
        write_json(
            &directory.join(format!("checkpoint-{leg:03}.json")),
            &record,
        )?;
        current_seeds = answer
            .branches
            .roots
            .iter()
            .map(|(symbol, value)| (*symbol, RootSeed::Value(value.clone())))
            .collect();
        current_boundary = diffexp::EpsilonBoundary {
            point: answer.solution.point.clone(),
            leading: 0,
            coefficients: answer.solution.coefficients.clone(),
        };
        last_answer = Some(answer);
    }
    let mut answer = last_answer.unwrap();
    answer.solution.diagnostics.steps = accepted;
    answer.solution.diagnostics.rejected_steps = rejected;
    let transport_seconds = transport.elapsed().as_secs_f64();
    if answer.solution.point != p.i(1)
        || answer.solution.coefficients.len() != 5
        || answer
            .solution
            .coefficients
            .iter()
            .any(|row| row.len() != 86 || row.iter().any(|v| !p.finite(v)))
        || answer.branches.roots.len() != root_names.len()
        || answer
            .branches
            .roots
            .iter()
            .zip(root_names)
            .any(|((actual, value), name)| *actual != symbol(name) || !p.finite(value))
    {
        return Err(Error::Numerical(
            "malformed or nonfinite full86 endpoint".into(),
        ));
    }
    let mut maximum = p.real(0);
    let mut differences = Vec::new();
    for (k, row) in answer.solution.coefficients.iter().enumerate() {
        for (j, value) in row.iter().enumerate() {
            let difference =
                p.norm(&p.sub(value, &scalar(p, &fixture["reference_by_epsilon"][k][j])?));
            if !difference.is_finite() {
                return Err(Error::Numerical("nonfinite reference difference".into()));
            }
            if difference > maximum {
                maximum = difference.clone();
            }
            differences.push(json!({"epsilon":k,"master_one_based":j+1,"absolute_difference":difference.to_string()}));
        }
    }
    let half = p.rational(&Rational::from((1, 2)));
    let mut root_records = Vec::new();
    let mut branch_pass = true;
    for (root, value) in &answer.branches.roots {
        let definition = pulled.roots.iter().find(|r| r.symbol == *root).unwrap();
        let exact_endpoint = symbolica_amflow::family::substitute(
            &definition.radicand,
            &BTreeMap::from([(Atom::var(parameter), Atom::one())]),
        )
        .together()
        .cancel();
        let radicand = p.eval(&exact_endpoint, &Default::default())?;
        let expected = p.pow(&radicand, &half);
        let difference = p.norm(&p.sub(value, &expected));
        branch_pass &=
            p.finite(&expected) && difference.is_finite() && difference < p.tolerance(128);
        root_records.push(json!({"root":Atom::var(*root).to_canonical_string(),"value":encoded(value),"principal_expected":encoded(&expected),"absolute_difference":difference.to_string()}));
    }
    let pass = maximum < p.tolerance(128) && branch_pass;
    let output = json!({"status":if pass {"passed"} else {"reference_or_branch_disagreement"},"case":"ZZZ86_PH1_PH2_128","working_digits":working,"order":order,"requested_mixed_digits":128,"asserted_reference_absolute_digits":128,"dimension":86,"epsilon_order":4,"symbolic_seconds":symbolic_seconds,"compile_seconds":compile_seconds,"contour_seconds":contour_seconds,"transport_seconds":transport_seconds,"total_seconds":clock.elapsed().as_secs_f64(),"checkpoint_scope":"Per-waypoint public transports preserve discrete branch hints; accepted+rejected budget is aggregate over all legs for this immutable controller. Checkpoints are unverified until an independent comparison.","steps":answer.solution.diagnostics.steps,"rejected_steps":answer.solution.diagnostics.rejected_steps,"values":answer.solution.coefficients.iter().map(|r|r.iter().map(encoded).collect::<Vec<_>>()).collect::<Vec<_>>(),"coefficient_differences":differences,"max_absolute_difference":maximum.to_string(),"branches":root_records,"crossings":route.crossings.iter().map(|r|json!({"point":encoded(&r.point),"side":format!("{:?}",r.side),"prescription_indices":r.prescription_indices})).collect::<Vec<_>>(),"waypoints":route.waypoints.iter().map(encoded).collect::<Vec<_>>(),"source_error_propagation_certificate":false,"precision_scope":"Low-level supplied-boundary transport checks128 absolute digits against stored PH2 values. Independent profile comparison remains separate. Source Accuracy132 and finite zeros are preserved in input, not promoted by working precision; a128-digit inherited-error certificate is not claimed by this result."});
    write_json(output_path, &output)?;
    if !pass {
        return Err(Error::Accuracy(format!(
            "ZZZ128 absolute endpoint residual {maximum}, branch_pass={branch_pass}"
        )));
    }
    Ok(())
}

