"""Run one reviewed, fixed-cap profile; never extend a live cap or overwrite runs."""
from pathlib import Path
import argparse,datetime,hashlib,json,os,resource,signal,subprocess,time
base=Path(__file__).resolve().parent;root=base.parents[1]
parser=argparse.ArgumentParser();parser.add_argument('profile',choices=['native_baseline','native_refined']);parser.add_argument('--name',required=True);parser.add_argument('--binary',type=Path);args=parser.parse_args()
plan=json.loads((base/'plan.json').read_text());profile=plan['profiles'][args.profile]
if Path(args.name).name!=args.name:raise SystemExit('Run name must be one path component')
work=base/'runs'/args.name;work.mkdir(parents=True,exist_ok=False)
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
for item in plan['source_files'].values():
 if sha(item['path'])!=item['sha256']:raise SystemExit(f'Changed pinned input: {item["path"]}')
env=os.environ.copy();env.pop('RUSTFLOW_PREPARE_ONLY',None);env.update(OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',RUSTFLOW_WOLFRAM_KERNEL='/home/ben/.local/bin/bern-wolfram',ZZZ_RUN_DIR=str(work))
if args.profile=='original':
 command=[str(root/'scripts/wolfram_one_thread.py'),'-noinit','-noprompt','-script',str(base/'original.wl')]
 expected=work/'result.json';extra={'driver_sha256':sha(base/'original.wl'),'launcher_sha256':sha(root/'scripts/wolfram_one_thread.py'),'loader_sha256':sha(root/'scripts/wolfram_one_thread.wl')}
else:
 if args.binary is None or not args.binary.is_file():raise SystemExit('Native profile requires an explicitly built --binary')
 build=json.loads((base/'native-checkpointed-build.json').read_text())
 if build['status']!='compiled' or sha(args.binary)!=build['binary_sha256'] or sha(base/'native_checkpointed.rs')!=build['source_sha256']:raise SystemExit('Checkpointed driver/build mismatch')
 if sha(build['library']['path'])!=build['library']['sha256']:raise SystemExit('Frozen library mismatch')
 if sha(build['dependency_snapshot']['path'])!=build['dependency_snapshot']['sha256']:raise SystemExit('Dependency archive manifest mismatch')
 command=[str(args.binary.resolve()),str(profile['working_digits']),str(profile['series_order']),str(base/'native-input.json'),str(work/'native-result.json')]
 expected=work/'native-result.json';extra={'binary_sha256':sha(args.binary),'driver_sha256':sha(base/'native_checkpointed.rs'),'library':build['library'],'dependency_snapshot':build['dependency_snapshot'],'build_manifest_sha256':sha(base/'native-checkpointed-build.json'),'launcher_sha256':sha(Path(__file__)),'checkpoint_scope':'Per-waypoint unverified diagnostic points, no automatic restart or source-error certificate','actual_native_predicate_budget':30000}
command=['taskset','-c',str(profile['cpu']),*command]
metadata={'status':'launched','started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':command,'profile':profile,'plan_sha256':sha(base/'plan.json'),'input_sha256':sha(base/'native-input.json'),'implementation':args.profile,**extra,'resource_scope':'Inherited per-process RLIMIT_AS plus0.25-second descendant RSS polling with PID-start-time checks. Polling is not a kernel-enforced aggregate limit and can miss short-lived descendants.'}
(work/'provenance.json').write_text(json.dumps(metadata,indent=2)+'\n')
cap=profile['per_process_address_space_bytes'];tracked={}
def limit():resource.setrlimit(resource.RLIMIT_AS,(cap,cap))
def state(pid):
 try:
  f=Path(f'/proc/{pid}/stat').read_text().rsplit(')',1)[1].split();return {'pid':pid,'ppid':int(f[1]),'start_ticks':int(f[19]),'rss':int(f[21])*os.sysconf('SC_PAGE_SIZE')}
 except (OSError,ValueError,IndexError):return None
def living(root_pid):
 allstates={}
 for q in Path('/proc').glob('[0-9]*/stat'):
  x=state(int(q.parent.name))
  if x:allstates[x['pid']]=x
 if root_pid not in tracked and root_pid in allstates:tracked[root_pid]=allstates[root_pid]
 found={pid:allstates[pid] for pid,old in tracked.items() if pid in allstates and allstates[pid]['start_ticks']==old['start_ticks']}
 while True:
  new={pid:x for pid,x in allstates.items() if pid not in found and x['ppid'] in found}
  if not new:break
  found.update(new)
 tracked.update(found);return found
def signal_owned(processes,sig):
 for pid,old in processes.items():
  now=state(pid)
  if now and now['start_ticks']==old['start_ticks']:
   try:os.kill(pid,sig)
   except ProcessLookupError:pass
start=time.monotonic();reason=None;peak=0
with (work/'run.log').open('w') as log,(work/'descendants.jsonl').open('w') as observations:
 proc=subprocess.Popen(command,cwd=work,env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True,preexec_fn=limit)
 while proc.poll() is None:
  processes=living(proc.pid);rss=sum(x['rss'] for x in processes.values());peak=max(peak,rss);elapsed=time.monotonic()-start
  observations.write(json.dumps({'elapsed_seconds':elapsed,'aggregate_descendant_rss':rss,'processes':list(processes.values())})+'\n');observations.flush()
  if elapsed>profile['wall_seconds']:reason='wall_limit'
  if rss>profile['aggregate_descendant_rss_poll_bytes']:reason='polled_rss_limit'
  if reason:
   signal_owned(living(proc.pid),signal.SIGTERM)
   try:proc.wait(timeout=5)
   except subprocess.TimeoutExpired:pass
   signal_owned(living(proc.pid),signal.SIGKILL);proc.wait();break
  time.sleep(.25)
 code=proc.returncode
 remaining=living(proc.pid)
 if remaining:signal_owned(remaining,signal.SIGTERM);time.sleep(1);signal_owned(living(proc.pid),signal.SIGKILL)
passed=code==0 and reason is None and expected.is_file() and json.loads(expected.read_text()).get('status')=='passed'
result={'status':'passed' if passed else 'incomplete_or_failed','returncode':code,'limit_reason':reason,'elapsed_seconds':time.monotonic()-start,'peak_polled_descendant_rss_bytes':peak,'finished_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'provenance_sha256':sha(work/'provenance.json'),'log_sha256':sha(work/'run.log'),'descendant_log_sha256':sha(work/'descendants.jsonl'),'scientific_result_sha256':sha(expected) if expected.exists() else None}
(work/'runner-result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));raise SystemExit(0 if passed else 1)
